let t = flow.get('t') || 0;
t = t + 1;
flow.set('t', t);
const fault = flow.get('fault') || false;
// ---- CNC-LATHE-01 数控车床 ----
let spindle = 3000 + 600 * Math.sin(t / 9);
let load    = 45 + 35 * Math.sin(t / 11);
let cool    = 38 + 12 * Math.sin(t / 15);
let status  = 1;
let estop   = 0;
if (fault) { cool = 75; status = 2; }
// ---- MACHINING-01 立式加工中心 ----
let feed   = 1600 + 400 * Math.sin(t / 7);
let power  = 14 + 6 * Math.sin(t / 13);
let mLoad  = 50 + 30 * Math.sin(t / 8);
let mStatus = 1;
let mEstop  = 0;
// 26 个寄存器 = 52 字节，一次写到 address 0（间隙补 0）
const buf = Buffer.alloc(52);
buf.writeFloatBE(spindle, 0);   // idx0-1  4x0001
buf.writeFloatBE(load, 4);      // idx2-3  4x0003
buf.writeFloatBE(cool, 8);      // idx4-5  4x0005
buf.writeUInt16BE(status, 12);  // idx6    4x0007
buf.writeUInt16BE(estop, 14);   // idx7    4x0008
buf.writeFloatBE(feed, 20);     // idx10-11 4x0011
buf.writeFloatBE(power, 40);    // idx20-21 4x0021
buf.writeFloatBE(mLoad, 44);    // idx22-23 4x0023
buf.writeUInt16BE(mStatus, 48); // idx24    4x0025
buf.writeUInt16BE(mEstop, 50);  // idx25    4x0026
msg.payload = { value: Array.from(buf), register: 'holding', address: 0, disableMsgOutput: 1 };
msg.topic = 'sim';
return msg;

flow.set('fault', true);
node.status({ fill: 'red', shape: 'ring', text: 'fault injected' });
return null;

flow.set('fault', false);
flow.set('t', 0);
const buf = Buffer.alloc(52, 0);
msg.payload = { value: Array.from(buf), register: 'holding', address: 0, disableMsgOutput: 1 };
msg.topic = 'reset';
node.status({ fill: 'green', shape: 'dot', text: 'reset done' });
return msg;
